struct Fuzz {
public protocol MessageConnection {
  /// Send a message to the peer.
  func sendMessage/*c*/<TX: Encodable>(_ message: TX)  throws
  /// Wait until receiving a message from the peer, and return it.
  func waitForNextMessage<RX: Decodable>(_ type: RX.Type /* c */ ) throws -> RX?
}
}
